
var Login = function() {

    var usercontextpath;
	/**
	 * 改变验证码的值
	 */
	var changeVerifyCode = function (action) {
		//console.log ("changeVerifyCode");
		var random = Math.random() * 10000000;
		
		$("#verifyCodeImg").attr("src", action+"?random=" + random);
        $("#rverifyCodeImg").attr("src", action+"?random=" + random);
	};
    var handleLogin = function() {

        $('.login-form').validate({
            errorElement: 'span', //default input error message container
            errorClass: 'help-block', // default input error message class
            focusInvalid: false, // do not focus the last invalid input
            rules: {
            	userName: {
                    required: true
                },
                password: {
                    required: true
                },
                remember: {
                    required: false
                },
                verifyCode: {
                    required: true
                }
            },

            messages: {
            	userName: {
                    required: "请输入用户名."
                },
                password: {
                    required: "请输入密码."
                },
                verifyCode: {
                	required: "请输入验证码."
                }
            },

            invalidHandler: function(event, validator) { //display error alert on form submit   
                $('.alert-danger', $('.login-form')).show();
            },

            highlight: function(element) { // hightlight error inputs
                $(element)
                    .closest('.form-group').addClass('has-error'); // set error class to the control group
            },

            success: function(label) {
                label.closest('.form-group').removeClass('has-error');
                label.remove();
            },

            errorPlacement: function(error, element) {
                error.insertAfter(element.closest('.input-icon'));
            },

            submitHandler: function(form) {
                form.submit(); // form validation success, call ajax form submit
            }
        });

        $('.login-form input').keypress(function(e) {
            if (e.which == 13) {
                if ($('.login-form').validate().form()) {
                    $('.login-form').submit(); //form validation success, call ajax form submit
                }
                return false;
            }
        });
    }

    var handleForgetPassword = function() {
        $('.forget-form').validate({
            errorElement: 'span', //default input error message container
            errorClass: 'help-block', // default input error message class
            focusInvalid: false, // do not focus the last invalid input
            ignore: "",
            rules: {
                email: {
                    required: true,
                    email: true
                }
            },

            messages: {
                email: {
                    required: "Email is required."
                }
            },

            invalidHandler: function(event, validator) { //display error alert on form submit   

            },

            highlight: function(element) { // hightlight error inputs
                $(element)
                    .closest('.form-group').addClass('has-error'); // set error class to the control group
            },

            success: function(label) {
                label.closest('.form-group').removeClass('has-error');
                label.remove();
            },

            errorPlacement: function(error, element) {
                error.insertAfter(element.closest('.input-icon'));
            },

            submitHandler: function(form) {
                form.submit();
            }
        });

        $('.forget-form input').keypress(function(e) {
            if (e.which == 13) {
                if ($('.forget-form').validate().form()) {
                    $('.forget-form').submit();
                }
                return false;
            }
        });

        jQuery('#forget-password').click(function() {
            jQuery('.login-form').hide();
            jQuery('.forget-form').show();
        });

        jQuery('#back-btn').click(function() {
            jQuery('.login-form').show();
            jQuery('.forget-form').hide();
        });

    }


    $.validator.addMethod("onlyLetterAndDigit",function(value, element, params){
        var regex=new RegExp('^[0-9a-zA-Z]+$');
        return regex.test(value);
    },"只能输入英文数字组合.");


    var handleRegister = function() {

        $('.register-form').validate({
            errorElement: 'span', //default input error message container
            errorClass: 'help-block', // default input error message class
            focusInvalid: false, // do not focus the last invalid input
            ignore: "",
            rules: {
                userName: {
                    required: true,
                    onlyLetterAndDigit:true
                },
                password: {
                    required: true,
                    minlength:6
                },
                rpassword: {
                    equalTo: "#register_password",
                    minlength:6
                },
                email: {
                    required: true,
                    email: true
                },
                rverifyCode: {
                    required: true
                }
            },

            messages: { // custom messages for radio buttons and checkboxes
                userName: {
                    required: "请输入英文用户名.",
                    onlyLetterAndDigit:"用户名不能为中文."
                },
                password: {
                    required: "请输入密码.",
                    minlength: "请输入6位以上密码."

                },
                rpassword: {
                    required: "请输入确认密码.",
                    equalTo: "两次密码不一致.",
                    minlength: "请输入6位以上密码."

                },
                email: {
                    required: "请输入邮箱地址.",
                    email: "请输入正确的邮件地址."
                },
                rverifyCode: {
                    required: "请输入验证码."
                }
            },

            invalidHandler: function(event, validator) { //display error alert on form submit   

            },

            highlight: function(element) { // hightlight error inputs
                $(element)
                    .closest('.form-group').addClass('has-error'); // set error class to the control group
            },

            success: function(label) {
                label.closest('.form-group').removeClass('has-error');
                label.remove();
            },

            errorPlacement: function(error, element) {
                if (element.attr("name") == "tnc") { // insert checkbox errors after the container                  
                    error.insertAfter($('#register_tnc_error'));
                } else if (element.closest('.input-icon').size() === 1) {
                    error.insertAfter(element.closest('.input-icon'));
                } else {
                    error.insertAfter(element);
                }
            },

            submitHandler: function(form) {
                var userName = $("#reg_userName").val();
                $.ajax({
                    type: "POST",
                    url : usercontextpath+"/sysmanager/user/checkuserexist.page",
                    data :{"userAccount": userName},
                    dataType : 'json',
                    async:false,
                    beforeSend: function(XMLHttpRequest){

                    },
                    success : function(responseText){
                        if(responseText=="exist"){
                            $('.msg','.alert-danger', $('.register-form')).text("用户"+userName+"已被占用!");
                            $('.alert-danger', $('.register-form')).show();
                        }else{
                            // $('.msg','.alert-danger', $('.login-form')).text("用户"+userName+"没有被占用，可以使用!");
                            var param = $(".register-form").serialize();
                            $.post(usercontextpath+"/registeruser/registerUser.page", param,
                                function(data){
                                    debugger;
                                    var json = data
                                    var n = eval(data)
                                    if (json.code > 0) {
                                        //$('.msg','.alert-danger', $('.register-form')).text(json.msg);
                                        //$('.alert-danger', $('.register-form')).show();
                                        PDP.success(json.msg);
                                        jQuery('.login-form').show();
                                        jQuery('.register-form').hide();
                                    } else {
                                       // $('.msg','.alert-danger', $('.register-form')).text(json.msg);
                                       // $('.alert-danger', $('.register-form')).show();
                                        PDP.warn(json.msg);
                                    }
                                },'json');
                        }
                    }
                });
            }
        });

        $('.register-form input').keypress(function(e) {
            if (e.which == 13) {
                if ($('.register-form').validate().form()) {
                   // $('.register-form').submit();
                }
                return false;
            }
        });

        jQuery('#register-btn').click(function() {
            jQuery('.login-form').hide();
            jQuery('.register-form').show();
        });

        jQuery('#register-back-btn').click(function() {
            jQuery('.login-form').show();
            jQuery('.register-form').hide();
        });
    }

    return {
        //main function to initiate the module
        init: function(relativepath) {
            usercontextpath = relativepath;
            handleLogin();
            handleForgetPassword();
            handleRegister();

        },
        changeVerifyCode:function(action)
        {
        	changeVerifyCode(action);
        }

    };

}();

